private lemma trace_le_factor_sum_d_sq (gp : GlobalParams) :
    (gp.R_beta * gp.R_beta.transpose).trace ≤
    (1 + (↑gp.m - 1) * gp.s ^ 2 / 4) * ∑ i : Fin gp.m, gp.d i ^ 2

private lemma RtransX_sq_le_trace_mul_norm (gp : GlobalParams) (x : Fin gp.m → ℝ) :
    ∑ j : Fin gp.m, (∑ i : Fin gp.m, gp.R_beta i j * x i) ^ 2 ≤
    (gp.R_beta * gp.R_beta.transpose).trace * ∑ i : Fin gp.m, x i ^ 2

private lemma row_sq_sum_le (i : Fin p.m) :
    ∑ j : Fin p.m, p.R_beta i j * p.R_beta i j ≤
    p.alpha ^ 2 + (↑p.m - 1) * (p.s ^ 2 / 4 * p.alpha ^ 2)

private lemma pivotPrefix_mem_of_bound {n k : ℕ} (pivots : Fin k → Fin n)
    (s : ℕ) (hs : s ≤ k) (x : Fin n) (hx : x ∈ pivotPrefix pivots s) :
    ∃ j, j < s ∧ ∃ hj : j < k, x = pivots ⟨j, hj⟩

private lemma pivotPrefix_pivot_mem {n k : ℕ} (pivots : Fin k → Fin n)
    (s j : ℕ) (hj_s : j < s) (hj_k : j < k) :
    pivots ⟨j, hj_k⟩ ∈ pivotPrefix pivots s

private lemma inner_zero_of_support_disjoint_aux {k m : ℕ}
    (v w : EuclideanSpace ℝ (Fin k))
    (hv : ∀ i : Fin k, ¬(i.val < m) → v i = 0)
    (hw : ∀ i : Fin k, i.val < m → w i = 0) :
    @inner ℝ (EuclideanSpace ℝ (Fin k)) _ v w = 0
